python.code:
import requests

response = requests.post(
    'http://localhost:3000/api/v1/reminder/extract',
    headers={
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token
    },
    json={
        'text': 'Schedule a reminder to walk the dog at 5pm daily'
    }
)

data = response.json()
print(data)
